float rnd(float s) {
    return fract(sin(s) * 100000.);
}

float box(vec2 s, vec2 r, vec2 c){
    vec2 tmp =
        step(0., (r + s) - c) *
        step(0., c - s); 
    return tmp.x * tmp.y;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    float stp = floor(iTime * 20.);
    vec4 layers[5];

    for(int i=0;i<5;i++){
        float size = .2 + rnd(stp + float(i)) * .2;

        vec2 s = vec2(
            rnd(stp+float(i))-size*.5,
            rnd(stp+float(i)+10.)-size*.5
        );

        float clr = box(
            s,
            vec2(size),
            uv
        );

        layers[i] = vec4(clr, clr, clr, 1. - distance(uv, s + vec2(size)*.5)*2.);
    }

    vec4 result;
    for(int i=0;i<5;i++){
        result = clamp(result + layers[i] * layers[i].w, 0., 1.);
    }

    fragColor = vec4(result.xy * (uv), result.z, result.w);
}
